function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  brush.fillBleed(0.45);
  brush.fillTexture(1.0, 100);
  brush.beginShape(0.5);
  vertex(200, 50);
  vertex(200, 400);
  vertex(200, 400);
  vertex(200, 100);
  endShape(true);

  // Hill
  brush.fillBleed(0.2);
  brush.fillTexture(0.3, 30);
  brush.beginShape(0.3);
  vertex(100, 300);
  vertex(200, 360);
  vertex(300, 300);
  vertex(200, 260);
  endShape(true);

  // Grass hill
  brush.fillBleed(0.1);
  brush.fillTexture(0.4, 50);
  brush.beginShape(0.1);
  vertex(100, 340);
  vertex(200, 380);
  vertex(300, 340);
  vertex(200, 300);
  endShape(true);
}

