function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  //Horizon at 200 units long, rain falling out on top of it
  brush.fill("#ffdb00", 1);
  brush.beginShape();
  brush.vertex(200, 0);
  brush.vertex(120, 10);
  brush.vertex(140, 30);
  brush.vertex(0, 50);
  brush.endShape(true);

  //The background has undulating hills
  brush.fill("#70cc3f", 0.6);
  brush.beginShape();
  brush.vertex(200, 40);
  brush.vertex(220, 15);
  brush.vertex(200, 45);
  brush.vertex(180, 55);
  brush.endShape(true);

  //Sometimes towards the west, the horizon becomes darker, completing the first phase
  brush.fill("#6a4400", 0.4);
  brush.beginShape();
  brush.vertex(120, 10);
  brush.vertex(100, 65);
  brush.vertex(80, 85);
  brush.vertex(100, 120);
  brush.endShape(true);

  //Lakes around the hills catch the light, creating vivid blues
  brush.fill("#2391c9", 0.3);
  brush.beginShape();
  brush.vertex(220, 30);
  brush.vertex(250, 30);
  brush.vertex(270, 75);
  brush.vertex(250, 65);
  brush.endShape(true);

  brush.fill("#70cc3f", 1);
  brush.beginShape();
  brush.vertex(260, 65);
  brush.vertex(280, 65);
  brush.vertex(300, 135);
  brush.vertex(280, 145);
  brush.endShape(true);

  //Patches of shade under the hills
  brush.fill("#5b6065", 0.2);
  brush.beginShape();
  brush.vertex(180, 50);
  brush.vertex(140, 50);
  brush.vertex(120, 120);
  brush.vertex(140, 100);
  brush.endShape(true);
}

