function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // painting goes here
  stroke(brush.colorFrom('#f37027', 0.3));
  strokeWidth(20);
  strokeWeight(20);
  fill("#f37027", 0.3);
  const r = 400;
  const dr = 30;
  const columns = r / dr;
  const i = 0;
  const s = i * dr;
  for (let i = 0; i < columns; i++) {
    if (s < 400) {
      const x = s;
      const y = 400 - s;
      brush.circle(x, y, dr);
    } else {
      const y = s - 400;
      brush.circle(0, y, dr);
    }
  }
}
```

